import unittest

from solution import build_charge, parse_cents


class ParseCentsTests(unittest.TestCase):
    def test_valid_forms(self):
        cases = {
            "0": 0,
            "12": 1200,
            "12.3": 1230,
            "12.34": 1234,
            "+7.01": 701,
            "-0.05": -5,
            " -12.3 \t": -1230,
            "0002.04": 204,
            "-0": 0,
        }
        for text, expected in cases.items():
            with self.subTest(text=text):
                self.assertEqual(parse_cents(text), (True, expected))

    def test_invalid_forms(self):
        for text in ("", "   ", ".5", "1.", "1.234", "1,000", "1e2", "+", "--1", "1 2", "1\n2"):
            with self.subTest(text=text):
                self.assertEqual(parse_cents(text), (False, None))

    def test_non_string_raises(self):
        for value in (None, 12, 1.2, True, []):
            with self.assertRaises(TypeError):
                parse_cents(value)


class BuildChargeTests(unittest.TestCase):
    def test_success_and_description_stripping(self):
        record, error = build_charge("  Service fee  ", 3, "1.20", "3.60")
        self.assertIsNone(error)
        self.assertEqual(record, {
            "description": "Service fee",
            "quantity": 3,
            "unit_cents": 120,
            "total_cents": 360,
        })
        self.assertEqual(set(record), {"description", "quantity", "unit_cents", "total_cents"})

    def test_empty_description_is_skipped(self):
        self.assertEqual(build_charge(" \t ", 1, "bad", "bad"), (None, None))

    def test_invert_only_negative_quantities(self):
        self.assertEqual(build_charge("x", -4, "1", "4", True)[0]["quantity"], 4)
        self.assertEqual(build_charge("x", 4, "1", "4", True)[0]["quantity"], 4)
        self.assertEqual(build_charge("x", -4, "1", "-4", False)[0]["quantity"], -4)
        self.assertEqual(build_charge("x", 0, "0", "0", True)[0]["quantity"], 0)

    def test_recoverable_price_errors(self):
        self.assertEqual(build_charge("x", 1, "1.234", "1"), (None, "invalid unit price"))
        self.assertEqual(build_charge("x", 1, "1.00", "total"), (None, "invalid total price"))

    def test_type_errors(self):
        cases = [
            (1, 1, "1", "1"),
            ("x", True, "1", "1"),
            ("x", 1.0, "1", "1"),
            ("x", 1, 1, "1"),
            ("x", 1, "1", 1),
        ]
        for args in cases:
            with self.subTest(args=args):
                with self.assertRaises(TypeError):
                    build_charge(*args)


if __name__ == "__main__":
    unittest.main()

